  function activityWaterfall(lc) { const attempts = lc.attempts || []; if (!attempts.length) return `<p class="muted">No upstream attempts were recorded for this request.</p>`; return `<ol class="waterfall">${attempts.map((x, i) => { const kind = x.outcome === 'succeeded' ? 'good' : x.outcome === 'failed' ? 'bad' : x.outcome === 'cancelled' ? 'warn' : 'neutral'; return `<li class="waterfall-step ${kind}"><span class="waterfall-index">${i + 1}</span><div class="waterfall-body"><b>${esc(x.provider || 'provider')} · ${esc(x.deployment || 'deployment')}</b><small>${esc(x.kind || 'attempt')} · ${esc(x.outcome || 'started')}${x.status_code ? ' · HTTP ' + esc(x.status_code) : ''}${x.error_type ? ' · ' + esc(x.error_type) : ''}${x.retryable ? ' · retryable' : ''}</small></div><span class="waterfall-time">${x.ttft_ms ? esc(x.ttft_ms) + ' ms ttft' : x.latency_ms ? esc(x.latency_ms) + ' ms' : '—'}</span></li>`; }).join('')}</ol>`; }
  function activityDetail(lc) { const facts = [['Requested model', lc.requested_model], ['Public alias', lc.public_model], ['Resolved model', lc.resolved_model], ['Route profile', lc.route_profile], ['Virtual endpoint', lc.virtual_endpoint], ['Pool', lc.pool], ['Protocol adapter', lc.adapter], ['Streaming', lc.streaming ? 'yes' : 'no'], ['Terminal', lc.terminal || lc.state], ['Latency', lc.latency_ms ? lc.latency_ms + ' ms' : '—'], ['TTFT', lc.ttft_ms ? lc.ttft_ms + ' ms' : '—'], ['Usage', (lc.input_tokens || lc.output_tokens) ? `${num(lc.input_tokens)} in / ${num(lc.output_tokens)} out (${esc(lc.cost_basis || 'estimate')})` : 'not observed']]; const link = location.origin + location.pathname + '#activity/' + encodeURIComponent(lc.request_id); return `<div class="modal-backdrop" role="presentation"><section class="modal activity-detail" role="dialog" aria-modal="true" aria-labelledby="activity-detail-title"><div class="modal-head"><div><span class="eyebrow">Request lifecycle</span><h2 id="activity-detail-title">${esc(lc.request_id)}</h2></div><button class="button ghost" data-action="close-activity" aria-label="Close">×</button></div><div class="modal-body"><div class="activity-facts">${facts.map(([k, v]) => `<div><small>${esc(k)}</small><b>${esc(v == null || v === '' ? '—' : String(v))}</b></div>`).join('')}</div><h3 class="activity-sub">Attempt waterfall</h3>${activityWaterfall(lc)}<p class="muted">Waterfall reflects provider attempts actually observed on the authenticated event stream. A stale request is never presented as live.</p></div><div class="modal-foot"><button class="button ghost" data-action="close-activity">Close</button><button class="button secondary" data-action="copy" data-copy="${esc(link)}">Copy deep link</button></div></section></div>`; }
  function activityView() { const ev = filteredEvents(); return `<div class="workspace-toolbar"><div><span class="eyebrow">Operational history</span><p>Privacy-safe request signals, incidents and routing decisions from the backend stream.</p></div><button class="button ghost" data-action="refresh">Refresh now</button></div><div class="summary-strip activity-summary"><div><small>Buffered events</small><b>${num((state.snap.events || []).length)}</b></div><div><small>Requests</small><b>${num(state.snap.request_total)}</b></div><div><small>Event stream</small>${activityConnectionBadge()}</div><div><small>Storage</small><b>Privacy-safe</b></div></div><div class="activity-toolbar"><div class="segmented"><button class="${state.activityTab === 'live' ? 'active' : ''}" data-activity-tab="live">Live</button><button class="${state.activityTab === 'all' ? 'active' : ''}" data-activity-tab="all">All signals</button><button class="${state.activityTab === 'requests' ? 'active' : ''}" data-activity-tab="requests">Requests</button><button class="${state.activityTab === 'incidents' ? 'active' : ''}" data-activity-tab="incidents">Incidents</button></div><label class="search-box"><span>⌕</span><input id="activity-filter" type="search" value="${esc(state.activityQuery)}" placeholder="Filter model, route or event…"></label></div>${state.activityTab === 'live' ? `<div class="activity-filters"><label class="select-box">Provider <select id="activity-provider"><option value="">All providers</option>${activityProviderOptions().map(p => `<option value="${esc(p)}"${activityState().provider === p ? ' selected' : ''}>${esc(p)}</option>`).join('')}</select></label><label class="select-box">Status <select id="activity-state">${['all', 'active', 'stale', 'succeeded', 'failed', 'cancelled'].map(s => `<option value="${s}"${activityState().stateFilter === s ? ' selected' : ''}>${s === 'all' ? 'All states' : s}</option>`).join('')}</select></label><span class="muted">Auto-refresh every 3s · stale after ${num(Math.max(1, Math.round(activityState().staleAfter / 60)))} min</span></div>` : ''}<section class="panel activity-panel">${state.activityTab === 'live' ? activityLiveList() : eventList(ev)}</section>${requestDecisionTimeline()}${activityState().selected ? (() => { const selected = activityState().requests.find(x => x.request_id === activityState().selected); return selected ? activityDetail(selected) : ''; })() : ''}`; }
  function filteredEvents() { return (state.snap.events || []).slice().reverse().filter(e => { const text = JSON.stringify(e).toLowerCase(), q = state.activityQuery.toLowerCase(), incident = /error|fail|degrad|cooldown|incident/.test(text); return (!q || text.includes(q)) && (state.activityTab === 'all' || state.activityTab === 'requests' ? (state.activityTab === 'all' || !incident) : incident); }); }
  function fmtUSD(v) { const n = Number(v || 0); return n !== 0 && Math.abs(n) < 0.01 ? '$' + n.toFixed(4) : '$' + n.toFixed(2); }
  async function fetchKeys() { if (!canManageKeys()) { state.keysStatus = 'forbidden'; return { keys: [] }; } try { const k = await api('/admin/api/client-keys'); state.keysStatus = 'ok'; return k; } catch (e) { state.keysStatus = /403/.test(String((e && e.message) || '')) ? 'forbidden' : 'error'; return { keys: [] }; } }
  /* cost-page-logic:start — pure decision logic for the Budgets & Cost page. Kept dependency-free so behavioral tests can extract and execute it. budgetPanelState classifies what the Budgets panel may claim: 'forbidden' (the role cannot see key records — an empty list proves NOTHING about budgets), 'unavailable' (the key records could not be loaded), 'legacy' (records loaded but the backend does not expose budget_usd — the budget backend is not available on this gateway), 'none' (records loaded, budget field exposed, no key configures a limit), 'some' (at least one configured limit), 'loading' (not fetched yet). */
  function budgetPanelState(keysStatus, keys) { if (keysStatus === 'forbidden') return { kind: 'forbidden', budgeted: [] }; if (keysStatus === 'error') return { kind: 'unavailable', budgeted: [] }; if (keysStatus !== 'ok') return { kind: 'loading', budgeted: [] }; const list = Array.isArray(keys) ? keys : []; if (list.length && list.every(k => !k || !Object.prototype.hasOwnProperty.call(k, 'budget_usd'))) return { kind: 'legacy', budgeted: [] }; const budgeted = list.filter(k => Number((k && k.budget_usd) || 0) > 0); return budgeted.length ? { kind: 'some', budgeted } : { kind: 'none', budgeted: [] }; }
  function identityShownNote(total) { return total > 100 ? bt('cost_showing', {n: total}) : ''; }
  /* cost-page-logic:end */
  function costAmount(d) { const basis = d.cost_basis || 'estimated'; if (basis === 'unknown') return `<b>—</b> <small class="muted">(unknown)</small>`; const cls = basis === 'recorded' ? 'cost-actual' : 'cost-estimated'; return `<b class="${cls}">${fmtUSD(d.estimated_cost_usd)}</b> <small class="muted">(${esc(basis)})</small>`; }
  function costTotalAmount(u, total) { const basis = u.total_cost_basis || ''; if (basis === 'unknown') return `<b>—</b> <small class="muted">(unknown)</small>`; const cls = basis === 'recorded' ? 'cost-actual' : 'cost-estimated'; return `<b class="${cls}">${fmtUSD(total)}</b>${basis ? ` <small class="muted">(${esc(basis)})</small>` : ''}`; }
  function costView() { const u = state.snap.usage || {}, deps = (u.by_deployment || []).slice().sort((a, b) => Number(b.estimated_cost_usd || 0) - Number(a.estimated_cost_usd || 0)), total = Number(u.total_estimated_cost_usd || 0); const panel = budgetPanelState(state.keysStatus, state.keys), budgeted = panel.budgeted; const head = `<div class="workspace-toolbar"><div><span class="eyebrow">${bt('cost_eyebrow')}</span><p>${bt('cost_desc')}</p></div><div class="tile-actions"><button class="button ghost" data-action="download-usage">${bt('cost_id_csv')}</button><button class="button secondary" data-action="export-cost-csv">${bt('cost_dep_csv')}</button><button class="button secondary" data-action="export-cost-json">${bt('cost_json')}</button></div></div>`; const strip = `<div class="summary-strip"><div><small>${bt('cost_s_est')}</small>${costTotalAmount(u, total)}</div><div><small>${bt('cost_s_req')}</small><b>${num(u.total_requests || 0)}</b></div><div><small>${bt('cost_s_in')}</small><b>${num(u.total_prompt_tokens || 0)}</b></div><div><small>${bt('cost_s_out')}</small><b>${num(u.total_completion_tokens || 0)}</b></div></div>`; const depTable = deps.length ? `<section class="panel activity-panel"><div class="section-heading compact"><div><h3>${bt('cost_by_dep')}</h3></div></div><div class="event-table cost-table"><div class="event-table-head"><span>${bt('cost_h_dep')}</span><span>${bt('cost_s_req')}</span><span>${bt('cost_h_tokens')}</span><span>${bt('cost_s_est')}</span><span>${bt('cost_h_share')}</span></div>${deps.map(d => `<article class="event-row"><span><b>${esc(d.deployment)}</b></span><span>${num(d.requests || 0)}</span><span>${num(d.prompt_tokens || 0)} / ${num(d.completion_tokens || 0)}</span><span>${costAmount(d)}</span><span class="score-bar"><i style="width:${total > 0 ? Math.max(1, Math.round(Number(d.estimated_cost_usd || 0) / total * 100)) : 0}%"></i></span></article>`).join('')}</div></section>` : `<div class="empty-state"><div class="empty-icon">$</div><h3>${bt('cost_empty')}</h3><p>${bt('cost_empty_d')}</p></div>`; const idTable = state.usage.length ? `<section class="panel activity-panel"><div class="section-heading compact"><div><h3>${bt('cost_by_id')}</h3></div></div><div class="event-table cost-table"><div class="event-table-head"><span>${bt('cost_h_id')}</span><span>${bt('cost_h_tenant')}</span><span>${bt('cost_s_req')}</span><span>${bt('cost_s_in')}</span><span>${bt('cost_s_out')}</span></div>${state.usage.slice(0, 100).map(row => `<article class="event-row"><span><b>${esc(row.identity || '—')}</b><small>${esc(row.project_id || row.team_id || '')}</small></span><span>${esc(row.tenant_id || '—')}</span><span>${num(row.requests)}</span><span>${num(row.input_tokens)}</span><span>${num(row.output_tokens)}</span></article>`).join('')}</div>${identityShownNote(state.usage.length) ? `<p class="muted">${esc(identityShownNote(state.usage.length))}</p>` : ''}</section>` : ''; const budgetViews = { some: { badge: bt('cost_budgeted', {n: num(budgeted.length)}), body: `<div class="check-list">${budgeted.map(k => `<div class="model-row"><span><b>${esc(k.name || k.id)}</b><small>${esc(k.tenant_id || bt('cost_no_tenant'))}</small></span><span class="subtle">${bt('cost_limit', {amount: fmtUSD(k.budget_usd)})}</span></div>`).join('')}</div>` }, none: { badge: bt('cost_b_none'), body: `<p class="muted">${bt('cost_b_none_d')}</p>` }, legacy: { badge: bt('cost_b_legacy'), body: `<p class="muted">${bt('cost_b_legacy_d')}</p>` }, forbidden: { badge: bt('cost_b_forbidden'), body: `<p class="muted">${bt('cost_b_forbidden_d')}</p>` }, unavailable: { badge: bt('cost_b_unavail'), body: `<p class="muted">${bt('cost_b_unavail_d')}</p>` }, loading: { badge: bt('cost_b_loading'), body: `<p class="muted">${bt('cost_b_loading_d')}</p>` } }; const bv = budgetViews[panel.kind] || budgetViews.loading; const budgets = `<section class="panel"><div class="section-heading compact"><div><h3>${bt('cost_budgets')}</h3><p>${bt('cost_budgets_d')}</p></div><span class="settings-badge">${bv.badge}</span></div>${bv.body}</section>`; return head + strip + depTable + idTable + budgets; }
  function downloadBlob(name, type, text) { const blob = new Blob([text], { type }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = name; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url); }
  function exportCostCSV() { const deps = (state.snap.usage || {}).by_deployment || []; const q = v => `"${String(v ?? '').replace(/"/g, '""')}"`; const lines = [['deployment', 'requests', 'prompt_tokens', 'completion_tokens', 'estimated_cost_usd', 'cost_basis'].join(','), ...deps.map(d => [q(d.deployment), d.requests || 0, d.prompt_tokens || 0, d.completion_tokens || 0, Number(d.estimated_cost_usd || 0), q(d.cost_basis || 'estimated')].join(','))]; downloadBlob('nexaroute-cost-by-deployment.csv', 'text/csv', lines.join('\n')); notice('Deployment cost CSV downloaded.'); }
