  function bindAccess() { $('#access-filter')?.addEventListener('input', e => { state.accessQuery = e.target.value; render(); $('#access-filter')?.focus(); }); }
  function accessView() { const q = (state.accessQuery || '').toLowerCase(), list = state.keys.filter(k => !q || JSON.stringify(k).toLowerCase().includes(q)), active = state.keys.filter(k => !k.revoked).length, tenants = new Set(state.keys.map(k => k.tenant_id).filter(Boolean)).size; return `<div class="workspace-toolbar"><div><span class="eyebrow">${bt('acc_eyebrow')}</span><p>${bt('acc_desc')}</p></div><button class="button primary" data-action="create-key">+ ${bt('acc_create')}</button></div><div class="summary-strip"><div><small>${bt('acc_s_keys')}</small><b>${num(state.keys.length)}</b></div><div><small>${bt('acc_s_active')}</small><b>${num(active)}</b></div><div><small>${bt('acc_s_revoked')}</small><b>${num(state.keys.length - active)}</b></div><div><small>${bt('acc_s_tenants')}</small><b>${num(tenants)}</b></div></div><div class="list-toolbar"><label class="search-box"><span>⌕</span><input id="access-filter" type="search" value="${esc(state.accessQuery)}" placeholder="${bt('acc_search')}"></label><span class="subtle">${bt('acc_writeonly')}</span></div>${list.length ? `<section class="panel"><div class="event-table access-table"><div class="event-table-head"><span>${bt('acc_h_key')}</span><span>${bt('acc_h_scope')}</span><span>${bt('acc_h_limits')}</span><span>${bt('acc_h_usage')}</span><span>${bt('acc_h_status')}</span><span></span></div>${list.map(k => { const u = keyUsageRow(k); const models = (k.allowed_models || []).length, routes = (k.allowed_routes || []).length; return `<article class="event-row"><span><b>${esc(k.name || k.id)}</b><small><code>${esc(k.id)}</code> · ${esc(k.role || 'developer')}</small></span><span><b>${esc(k.tenant_id || '—')}</b><small>${esc(k.project_id || '')}${k.project_id && k.team_id ? ' · ' : ''}${esc(k.team_id || '')}${!k.project_id && !k.team_id ? bt('acc_no_scope') : ''}</small></span><span><b>${k.rpm ? bt('acc_rpm_v', {n: num(k.rpm)}) : bt('acc_no_rpm')}${k.tpm ? bt('acc_tpm_v', {n: num(k.tpm)}) : ''}</b><small>${models ? bt('acc_models_n', {n: models}) : bt('acc_models_all')} · ${routes ? bt('acc_routes_n', {n: routes}) : bt('acc_routes_all')}${k.require_privacy ? ' · ' + bt('acc_no_training') : ''}</small></span><span><b>${u ? bt('acc_req_v', {n: num(u.requests)}) : '—'}</b><small>${u ? bt('acc_tokens_v', {i: num(u.input_tokens), o: num(u.output_tokens)}) : bt('acc_no_usage')}</small></span>${statusPill(k.revoked ? bt('acc_s_revoked') : bt('acc_s_active'), k.revoked ? 'bad' : 'good')}<span class="tile-actions">${k.revoked ? '' : `<button class="button ghost small" data-action="rotate-key" data-id="${esc(k.id)}">${bt('acc_rotate')}</button><button class="button danger small" data-action="revoke-key" data-id="${esc(k.id)}">${bt('acc_revoke')}</button>`}</span></article>`; }).join('')}</div></section>` : `<div class="empty-state"><div class="empty-icon">⚿</div><h3>${state.keys.length ? bt('acc_empty_match') : bt('acc_empty_none')}</h3><p>${state.keys.length ? bt('acc_empty_match_d') : bt('acc_empty_none_d')}</p><button class="button primary" data-action="create-key">${bt('acc_create')}</button></div>`}`; }
  async function loadAudit() { if (state.auditLoading) return; state.auditLoading = true; state.auditError = ''; try { const res = await api(`/admin/api/audit?limit=${state.auditLimit}`); state.audit = res.events || []; state.auditLoaded = true; } catch (e) { state.auditError = /403/.test(e.message) ? 'forbidden' : e.message; state.auditLoaded = true; } finally { state.auditLoading = false; if (state.page === 'audit') render(); } }
  function ensureAudit() { if (!state.auditLoaded && !state.auditLoading) loadAudit(); }
  function bindAudit() { $('#audit-filter')?.addEventListener('input', e => { state.auditQuery = e.target.value; render(); $('#audit-filter')?.focus(); }); $('#audit-outcome')?.addEventListener('change', e => { state.auditOutcome = e.target.value; render(); }); $('#audit-limit')?.addEventListener('change', e => { state.auditLimit = Number(e.target.value || 500); state.auditLoaded = false; ensureAudit(); render(); }); }
  function auditFiltered() { const q = (state.auditQuery || '').toLowerCase(); return (state.audit || []).filter(ev => { const failed = Number(ev.status || 0) >= 400 || /denied|fail/i.test(String(ev.outcome || '')); if (state.auditOutcome === 'ok' && failed) return false; if (state.auditOutcome === 'failed' && !failed) return false; if (!q) return true; return JSON.stringify(ev).toLowerCase().includes(q); }); }
  function auditLinkage() { const chained = (state.audit || []).filter(ev => Number(ev.seq || 0) > 0).slice().sort((a, b) => Number(a.seq) - Number(b.seq)); let checked = 0, broken = 0; for (let i = 1; i < chained.length; i++) { if (Number(chained[i].seq) === Number(chained[i - 1].seq) + 1) { checked++; if (chained[i].prev_hash !== chained[i - 1].hash) broken++; } } return { chained: chained.length, legacy: (state.audit || []).length - chained.length, checked, broken }; }
  function auditView() { const rows = auditFiltered(), link = auditLinkage(); const head = `<div class="workspace-toolbar"><div><span class="eyebrow">${bt('aud_eyebrow')}</span><p>${bt('aud_desc', {cmd: '<code>nexaroute audit verify</code>'})}</p></div><div class="tile-actions"><button class="button ghost" data-action="reload-audit">${bt('aud_reload')}</button><button class="button secondary" data-action="export-audit-json">${bt('aud_export_json')}</button><button class="button secondary" data-action="export-audit-csv">${bt('aud_export_csv')}</button></div></div>`; if (state.auditError === 'forbidden') return head + `<div class="empty-state"><div class="empty-icon">▤</div><h3>${bt('aud_forbidden')}</h3><p>${bt('aud_forbidden_d')}</p></div>`; if (state.auditError) return head + `<div class="empty-state"><div class="empty-icon">!</div><h3>${bt('aud_unavailable')}</h3><p>${esc(state.auditError)}</p></div>`; if (!state.auditLoaded) return head + `<div class="empty-state"><div class="empty-icon">▤</div><h3>${bt('aud_loading')}</h3></div>`; const verdict = link.broken ? `<span class="status bad">${bt('aud_broken', {n: num(link.broken)})}</span>` : link.checked ? `<span class="status good">${bt('aud_verified', {n: num(link.checked)})}</span>` : `<span class="status warn">${bt('aud_no_pairs')}</span>`; return `${head}<div class="summary-strip"><div><small>${bt('aud_s_records')}</small><b>${num(state.audit.length)}</b></div><div><small>${bt('aud_s_chained')}</small><b>${num(link.chained)}</b></div><div><small>${bt('aud_s_legacy')}</small><b>${num(link.legacy)}</b></div><div><small>${bt('aud_s_linkage')}</small><b>${verdict}</b></div></div><div class="list-toolbar"><label class="search-box"><span>⌕</span><input id="audit-filter" type="search" value="${esc(state.auditQuery)}" placeholder="${bt('aud_search')}"></label><label class="field inline"><span>${bt('aud_outcome')}</span><select id="audit-outcome"><option value="all" ${state.auditOutcome === 'all' ? 'selected' : ''}>${bt('aud_all')}</option><option value="ok" ${state.auditOutcome === 'ok' ? 'selected' : ''}>${bt('aud_ok')}</option><option value="failed" ${state.auditOutcome === 'failed' ? 'selected' : ''}>${bt('aud_failed')}</option></select></label><label class="field inline"><span>${bt('aud_window')}</span><select id="audit-limit"><option ${state.auditLimit === 100 ? 'selected' : ''}>100</option><option ${state.auditLimit === 500 ? 'selected' : ''}>500</option><option ${state.auditLimit === 1000 ? 'selected' : ''}>1000</option></select></label></div>${rows.length ? `<section class="panel activity-panel"><div class="event-table audit-table"><div class="event-table-head"><span>${bt('ev_h_time')}</span><span>${bt('aud_h_actor')}</span><span>${bt('ev_h_target')}</span><span>${bt('aud_h_outcome')}</span><span>${bt('aud_h_chain')}</span></div>${rows.map(ev => `<article class="event-row"><time>${esc(formatTime(ev.timestamp))}</time><span><b>${esc(ev.actor || '—')}</b><small>${esc(ev.action || '')} ${esc(ev.method || '')} ${esc(ev.path || '')}</small></span><span><b>${esc(ev.target || '—')}</b><small>${esc(ev.request_id || '')}</small></span><span><b>${esc(ev.outcome || '')}</b><small>${bt('aud_http', {n: num(ev.status || 0)})}${ev.permission ? ` · ${esc(ev.permission)}` : ''}</small></span><span>${Number(ev.seq || 0) ? `<b>#${num(ev.seq)}</b><small><code>${esc(String(ev.hash || '').slice(0, 10))}…</code></small>` : `<small>${bt('aud_legacy')}</small>`}</span></article>`).join('')}</div></section>` : `<div class="empty-state"><div class="empty-icon">▤</div><h3>${bt('aud_empty')}</h3><p>${bt('aud_empty_d')}</p></div>`}`; }
  function exportAuditJSON() { downloadBlob('nexaroute-audit.json', 'application/json', JSON.stringify(auditFiltered(), null, 2)); notice('Audit JSON exported.'); }
  function exportAuditCSV() { const cols = ['timestamp', 'seq', 'actor', 'action', 'target', 'method', 'path', 'outcome', 'status', 'permission', 'request_id', 'hash']; const q = v => `"${String(v ?? '').replace(/"/g, '""')}"`; const lines = [cols.join(','), ...auditFiltered().map(ev => cols.map(c => q(ev[c])).join(','))]; downloadBlob('nexaroute-audit.csv', 'text/csv', lines.join('\n')); notice('Audit CSV exported.'); }  async function loadEvals() { if (state.evalsLoading) return; state.evalsLoading = true; state.evalsError = ''; try { const [cards, runs] = await Promise.all([api('/admin/api/scorecards?limit=200'), api('/admin/api/evaluation/runs?limit=20')]); state.cards = cards.scorecards || []; state.runs = runs.runs || []; state.evalsLoaded = true; } catch (e) { state.evalsError = e.message; state.evalsLoaded = true; } finally { state.evalsLoading = false; if (state.page === 'evals') render(); } }
  function ensureEvals() { if (!state.evalsLoaded && !state.evalsLoading) loadEvals(); }
  function evalsView() { const head = `<div class="workspace-toolbar"><div><span class="eyebrow">Model intelligence</span><p>Scorecards carry provenance for every value — a score without evidence never renders. Evaluation health is a separate namespace and never affects routing.</p></div><button class="button ghost" data-action="reload-evals">Reload</button></div>`; if (state.evalsError) return head + `<div class="empty-state"><div class="empty-icon">!</div><h3>Scorecards unavailable</h3><p>${esc(state.evalsError)}</p></div>`; if (!state.evalsLoaded) return head + `<div class="empty-state"><div class="empty-icon">✦</div><h3>Loading scorecards…</h3></div>`; const deps = deployments(); const runForm = `<section class="panel settings-card"><div class="section-heading compact"><div><h3>Run an evaluation</h3><p>Live runs call the deployment upstream; artifact runs score recorded outcomes. A disabled evaluation plane answers with its own message.</p></div><span class="settings-badge">evaluation.run</span></div><div class="form-grid"><div class="field"><label for="eval-deployment">Deployment</label><select id="eval-deployment">${deps.map(d => `<option value="${esc(d.id)}">${esc(d.id)}</option>`).join('')}</select></div><div class="field"><label for="eval-suite">Suite ID</label><input id="eval-suite" placeholder="suite id from evaluation config"></div></div><div class="tile-actions"><button class="button primary" data-action="run-eval">Run evaluation</button></div><div id="eval-run-result"></div></section>`; const cards = state.cards.length ? `<div class="provider-grid">${state.cards.map(c => { const dims = Object.entries(c.values || {}); return `<article class="provider-tile"><div class="tile-top"><div class="tile-title"><h3>${esc(c.deployment_id)}</h3><span>${esc(c.provider_id || '')} · ${esc(c.model || '')} · v${num(c.version || 0)} · ${esc(formatTime(c.generated_at))}</span></div></div>${dims.length ? dims.map(([dim, v]) => `<div class="score-row"><span><b>${esc(dim)}</b><small>${v.raw !== undefined ? `${num(v.raw)} ${esc(v.unit || '')} · ` : ''}${num(v.sample_count || 0)} samples · conf ${Number(v.confidence || 0).toFixed(2)} · ${esc(typeof v.provenance === 'string' ? v.provenance : (v.provenance?.kind || v.provenance?.source || 'recorded'))}</small></span><span class="score-bar"><i style="width:${Math.max(0, Math.min(100, Number(v.score || 0) * 100))}%"></i></span><b>${Number(v.score || 0).toFixed(2)}</b></div>`).join('') : '<p class="muted">No scored dimensions yet.</p>'}${(c.notes || []).length ? `<small class="muted">${c.notes.map(esc).join(' · ')}</small>` : ''}</article>`; }).join('')}</div>` : `<div class="empty-state"><div class="empty-icon">✦</div><h3>No scorecards yet</h3><p>Scorecards appear after an evaluation run or when evidence is recorded for a deployment.</p></div>`; const runs = state.runs.length ? `<section class="panel"><div class="section-heading compact"><div><h3>Recent runs</h3></div></div><div class="check-list">${state.runs.map(r => `<div class="model-row"><span><b>${esc(r.id || r.run_id || 'run')}</b><small>${esc(r.suite_id || '')} · ${esc(r.deployment_id || '')} · ${esc(formatTime(r.started_at || r.generated_at || ''))}</small></span><span class="subtle">${esc(r.status || r.outcome || '')}</span></div>`).join('')}</div></section>` : ''; return head + runForm + cards + runs; }
  function bindObservability() { $('#obs-save-links')?.addEventListener('click', () => { state.promURL = $('#obs-prom').value.trim(); state.grafanaURL = $('#obs-grafana').value.trim(); localStorage.setItem('nexaroute_prom_url', state.promURL); localStorage.setItem('nexaroute_grafana_url', state.grafanaURL); notice('Observability links saved in this browser.'); render(); }); }
  function observabilityView() { const rows = state.snap.health || []; return `<div class="workspace-toolbar"><div><span class="eyebrow">Signals</span><p>Live per-deployment health from the admin snapshot. Full latency and TTFT histograms (<code>nexaroute_deployment_request_latency_ms</code>, <code>nexaroute_deployment_ttft_ms</code>) are exposed on the Prometheus endpoint.</p></div><a class="button secondary" href="/metrics" target="_blank" rel="noopener">Open /metrics</a></div><section class="panel"><div class="section-heading compact"><div><h3>External dashboards</h3><p>Operator links, stored only in this browser.</p></div></div><div class="form-grid"><div class="field"><label for="obs-prom">Prometheus base URL</label><input id="obs-prom" type="url" value="${esc(state.promURL)}" placeholder="https://prometheus.internal"></div><div class="field"><label for="obs-grafana">Grafana base URL</label><input id="obs-grafana" type="url" value="${esc(state.grafanaURL)}" placeholder="https://grafana.internal"></div></div><div class="tile-actions"><button class="button secondary" id="obs-save-links">Save links</button>${state.promURL ? `<a class="button ghost" href="${esc(state.promURL)}" target="_blank" rel="noopener">Open Prometheus</a>` : ''}${state.grafanaURL ? `<a class="button ghost" href="${esc(state.grafanaURL)}" target="_blank" rel="noopener">Open Grafana</a>` : ''}</div><small class="muted">A starter dashboard and alert rules ship in <code>deploy/observability/</code>.</small></section>${rows.length ? `<section class="panel activity-panel"><div class="event-table obs-table"><div class="event-table-head"><span>Deployment</span><span>Status</span><span>Latency / TTFT</span><span>Errors</span><span>Last success</span></div>${rows.map(h => `<article class="event-row"><span><b>${esc(h.deployment)}</b><small>circuit ${esc(h.circuit_state || '—')}</small></span>${statusPill(h.state || h.status, statusClass(h.status))}<span><b>${Number(h.average_latency || h.ewma_latency_ms || 0).toFixed(0)} ms</b><small>ttft ${Number(h.ewma_ttft_ms || 0).toFixed(0)} ms</small></span><span><b>${(Number(h.recent_error_rate ?? h.ewma_failure_rate ?? 0) * 100).toFixed(1)}%</b><small>${num(h.successes || 0)} ok · ${num(h.failures || 0)} failed${h.consecutive_failures ? ` · ${num(h.consecutive_failures)} consecutive` : ''}</small></span><span><b>${esc(formatTime(h.last_success))}</b><small>${h.last_failure ? 'last failure ' + esc(formatTime(h.last_failure)) : 'no failures recorded'}</small></span></article>`).join('')}</div></section>` : `<div class="empty-state"><div class="empty-icon">◉</div><h3>No deployments reporting</h3><p>Health rows appear once providers and routes are configured.</p></div>`}`; }
  const guardrailClasses = [['pii_email', /\b[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}\b/i, 'reject_pii'], ['pii_phone', /\b(?:\+?\d[\d .()-]{8,}\d)\b/, 'reject_pii'], ['secret_api_key', /\b(?:sk-[A-Za-z0-9_-]{16,}|AKIA[0-9A-Z]{16}|gh[pousr]_[A-Za-z0-9_]{20,})\b/i, 'reject_secrets'], ['prompt_injection', /(ignore\s+(all|any|the)\s+previous\s+instructions|reveal\s+the\s+system\s+prompt|jailbreak\s+mode)/i, 'reject_prompt_injection']];
  function bindPolicies() { $('#sim-run')?.addEventListener('click', () => { const text = $('#sim-text')?.value || ''; const g = state.snap.config?.guardrails || {}; const found = guardrailClasses.filter(([, re]) => re.test(text)); const box = $('#sim-result'); if (!box) return; if ((g.mode || 'off') === 'off') { box.innerHTML = `<p class="muted">Guardrails are <b>off</b> — the server would not scan this request. ${found.length ? `The mirrored scan finds: ${found.map(f => esc(f[0])).join(', ')}.` : 'The mirrored scan finds nothing.'}</p>`; return; } const blocking = found.filter(([, , flag]) => g[flag]); box.innerHTML = found.length ? `<p>Findings (kinds only — content never leaves this browser): <b>${found.map(f => esc(f[0])).join(', ')}</b></p><p>${g.mode === 'block' ? (blocking.length ? `<span class="status bad">Would be REJECTED</span> — blocking classes: ${blocking.map(f => esc(f[0])).join(', ')}` : '<span class="status good">Would pass</span> — findings are in audit-only classes for the current flags.') : '<span class="status warn">Audit mode</span> — would pass and record a kinds-only guardrail event.'}</p>` : '<p><span class="status good">No findings</span> — the mirrored scan is clean; the server scan is authoritative.</p>'; }); }
  function policiesView() { const g = state.snap.config?.guardrails || {}, d = state.snap.config?.decision || {}, policies = state.snap.config?.decision_policies || []; const flagRow = (label, on) => `<div class="model-row"><span><b>${label}</b></span>${statusPill(on ? bt('pol_reject') : bt('pol_allow'), on ? 'bad' : 'good')}</div>`; return `<div class="workspace-toolbar"><div><span class="eyebrow">${bt('pol_eyebrow')}</span><p>${bt('pol_desc', {cmd: '<code>nexaroute policy</code>'})}</p></div></div><div class="settings-grid"><section class="panel settings-card"><div class="section-heading compact"><div><h3>${bt('pol_guardrails')}</h3><p>${bt('pol_guardrails_d')}</p></div><span class="settings-badge">${bt('pol_mode', {m: esc(g.mode || 'off')})}</span></div><div class="check-list">${flagRow(bt('pol_f_pii'), !!g.reject_pii)}${flagRow(bt('pol_f_secrets'), !!g.reject_secrets)}${flagRow(bt('pol_f_injection'), !!g.reject_prompt_injection)}</div><small class="muted">${bt('pol_bodycap', {n: num(g.max_body_bytes || 0)})}</small></section><section class="panel settings-card"><div class="section-heading compact"><div><h3>${bt('pol_sim')}</h3><p>${bt('pol_sim_d')}</p></div><span class="settings-badge">${bt('pol_local')}</span></div><div class="field full"><label for="sim-text">${bt('pol_sim_label')}</label><textarea id="sim-text" rows="5" placeholder="${bt('pol_sim_ph')}"></textarea></div><div class="tile-actions"><button class="button primary" id="sim-run">${bt('pol_scan')}</button></div><div id="sim-result"></div></section><section class="panel settings-card"><div class="section-heading compact"><div><h3>${bt('pol_decision')}</h3><p>${bt('pol_decision_d')}</p></div><span class="settings-badge">${esc(d.mode || 'off')}</span></div><div class="check-list"><div class="model-row"><span><b>${bt('ov_topo_unknown')}</b><small>${esc(d.provider || 'local')}</small></span></div><div class="model-row"><span><b>${bt('pol_active_policy')}</b><small>${esc(d.policy || 'none')}</small></span></div><div class="model-row"><span><b>${bt('pol_timeout')}</b><small>${bt('pol_ms', {n: num(d.timeout_ms || 0)})}</small></span></div></div></section><section class="panel settings-card"><div class="section-heading compact"><div><h3>${bt('pol_policies')}</h3><p>${bt('pol_policies_d')}</p></div><span class="settings-badge">${bt('pol_defined', {n: num(policies.length)})}</span></div>${policies.length ? `<div class="check-list">${policies.map(p => { const w = p.weights || {}; return `<div class="model-row"><span><b>${esc(p.name || p.id)}</b><small>${esc(p.id)} · ${esc(p.selection_mode || 'select_first')} · ${bt('pol_min_delta', {n: Number(p.min_score_delta || 0)})}</small><small>${bt('pol_weights', {b: w.router_baseline ?? '—', r: w.reliability ?? '—', l: w.latency ?? '—', t: w.ttft ?? '—', c: w.capacity ?? '—', co: w.cost ?? '—', cx: w.context ?? '—'})}${p.task_overrides ? ` · ${bt('pol_task_overrides', {n: Object.keys(p.task_overrides).length})}` : ''}</small></span>${d.policy === p.id ? statusPill(bt('pol_active'), 'good') : ''}</div>`; }).join('')}</div>` : `<p class="muted">${bt('pol_no_policies')}</p>`}</section>${autopilotCard()}</div>`; }
  function autopilotCard() { const a = state.snap.autopilot || {}; if (!a.enabled || !a.status) { return `<section class="panel settings-card"><div class="section-heading compact"><div><h3>${bt('pol_autopilot')}</h3><p>${bt('pol_autopilot_d')}</p></div><span class="settings-badge">off</span></div><p class="muted">${bt('pol_auto_disabled')}</p></section>`; } const s = a.status, inc = s.incumbent || {}, cand = s.candidate, rb = s.last_rollback; const badge = statusPill(esc(s.state || 'draft'), s.state === 'rolled_back' ? 'bad' : (s.state === 'canary' ? 'warn' : 'good')); const rows = `<div class="check-list"><div class="model-row"><span><b>${bt('pol_auto_incumbent')}</b><small>${esc(inc.id || '—')} · ${esc(inc.version || '')}</small></span></div>${cand ? `<div class="model-row"><span><b>${bt('pol_auto_candidate')}</b><small>${esc(cand.id || '')} · ${esc(cand.version || '')}</small></span></div>` : ''}${s.canary_percent ? `<div class="model-row"><span><b>${bt('pol_auto_canary', {n: num(s.canary_percent)})}</b></span></div>` : ''}<div class="model-row"><span><b>${bt('pol_auto_inflight', {n: num(s.in_flight || 0)})}</b></span></div></div>`; const rollback = rb ? `<p class="status bad">${bt('pol_auto_last_rollback', {v: esc(rb.bad_version || 'candidate'), r: esc(rb.restored_version || 'incumbent'), c: esc(rb.cause || '')})}</p>` : `<p class="muted">${bt('pol_auto_no_rollback')}</p>`; const incidents = (s.incidents || []).length ? `<small class="muted">${bt('pol_auto_incidents', {n: num((s.incidents || []).length)})}</small>` : ''; return `<section class="panel settings-card"><div class="section-heading compact"><div><h3>${bt('pol_autopilot')}</h3><p>${bt('pol_autopilot_d')}</p></div>${badge}</div>${rows}${rollback}${incidents}</section>`; }
  function pgRoute() { const models = routes(); if (!state.pgModel && models.length) state.pgModel = models[0].public_model; return models.find(v => v.public_model === state.pgModel) || null; }
  function pgExclusions() { const route = pgRoute(); if (!route) return []; const profile = (state.snap.route_profiles || []).find(p => p.id === route.route_profile) || {}; const pool = (state.snap.candidate_pools || []).find(p => p.id === profile.candidate_pool) || {}; const inPool = new Set(pool.deployments || []); const trains = pid => { const p = (state.snap.config?.providers || []).find(x => x.id === pid) || {}; return String(p.data_handling?.trains_on_data || 'unknown').toLowerCase(); }; return deployments().map(d => { const h = (state.snap.health || []).find(x => x.deployment === d.id) || {}; let reason = ''; if (pool.mode !== 'all' && inPool.size && !inPool.has(d.id)) reason = bt('pg_reason_pool'); else if (profile.privacy === 'no_training' && trains(d.provider_id) !== 'no') reason = bt('pg_reason_trains'); else if (h.status && !['healthy', 'ready'].includes(String(h.status).toLowerCase())) reason = bt('pg_reason_status', {s: h.status}); return { id: d.id, model: d.model, excluded: !!reason, reason: reason || bt('pg_eligible') }; }); }
  function playgroundView() { const route = pgRoute(), models = routes(); const excl = pgExclusions(); return `<div class="workspace-toolbar"><div><span class="eyebrow">${bt('pg_eyebrow')}</span><p>${bt('pg_desc')}</p></div></div><div class="settings-grid"><section class="panel settings-card"><div class="section-heading compact"><div><h3>${bt('pg_request')}</h3></div><span class="settings-badge">${bt('pg_data_plane')}</span></div><div class="form-grid"><div class="field"><label for="pg-protocol">${bt('pg_protocol')}</label><select id="pg-protocol"><option value="openai">OpenAI · /v1/chat/completions</option><option value="anthropic">Anthropic · /v1/messages</option></select></div><div class="field"><label for="pg-model">${bt('pg_model')}</label><select id="pg-model">${models.map(v => `<option value="${esc(v.public_model)}" ${v.public_model === state.pgModel ? 'selected' : ''}>${esc(v.public_model)}</option>`).join('')}</select></div><div class="field full"><label for="pg-key">${bt('pg_key')}</label><input id="pg-key" type="password" value="${esc(state.pgKey)}" autocomplete="off"></div><div class="field full"><label for="pg-system">${bt('pg_system')}</label><input id="pg-system"></div><div class="field full"><label for="pg-prompt">${bt('pg_prompt')}</label><textarea id="pg-prompt" rows="5" placeholder="${bt('pg_prompt_ph')}"></textarea></div><div class="field"><label for="pg-temp">${bt('pg_temp')}</label><input id="pg-temp" type="number" min="0" max="2" step="0.1" value="0.7"></div><div class="field"><label for="pg-max">${bt('pg_max')}</label><input id="pg-max" type="number" min="1" value="512"></div><div class="field"><label for="pg-stream">${bt('pg_stream')}</label><select id="pg-stream"><option value="false">${bt('pg_off')}</option><option value="true">${bt('pg_on')}</option></select></div></div><div class="tile-actions"><button class="button primary" id="pg-send">${bt('pg_send')}</button></div></section><section class="panel settings-card"><div class="section-heading compact"><div><h3>${bt('pg_exclusions')}</h3><p>${bt('pg_excl_d', {model: esc(route ? route.public_model : '—'), profile: route ? bt('pg_profile', {p: esc(route.route_profile)}) : ''})}</p></div></div>${excl.length ? `<div class="check-list">${excl.map(x => `<div class="model-row"><span><b>${esc(x.id)}</b><small>${esc(x.reason)}</small></span>${statusPill(x.excluded ? bt('pg_excluded') : bt('pg_eligible'), x.excluded ? 'bad' : 'good')}</div>`).join('')}</div>` : `<p class="muted">${bt('pg_no_deploy')}</p>`}</section></div><section class="panel"><div class="section-heading compact"><div><h3>${bt('pg_response')}</h3></div><span class="settings-badge" id="pg-status">${bt('pg_idle')}</span></div><div id="pg-trace" class="muted">${bt('pg_no_request')}</div><div class="field full"><label for="pg-out">${bt('pg_response_text')}</label><textarea id="pg-out" rows="8" readonly></textarea></div><details><summary>${bt('pg_raw')}</summary><pre class="code-block" id="pg-raw"></pre></details></section>`; }
  function bindPlayground() { $('#pg-model')?.addEventListener('change', e => { state.pgModel = e.target.value; render(); }); $('#pg-send')?.addEventListener('click', pgSend); }
  function pgPrices(deploymentID) { const [pid, mid] = String(deploymentID || '').split('/'); const p = (state.snap.config?.providers || []).find(x => x.id === pid); const m = (p?.models || []).find(x => x.id === mid); return m ? { input: Number(m.input_cost_per_mtok || 0), output: Number(m.output_cost_per_mtok || 0) } : null; }
  async function pgSend() { const proto = $('#pg-protocol').value, model = $('#pg-model').value, key = $('#pg-key').value.trim(); state.pgKey = key; if (key) sessionStorage.setItem('nexaroute_pg_key', key); else sessionStorage.removeItem('nexaroute_pg_key'); const prompt = $('#pg-prompt').value; if (!prompt) { notice('Enter a prompt first.', true); return; } const stream = $('#pg-stream').value === 'true'; const temp = Number($('#pg-temp').value || 0), max = Number($('#pg-max').value || 512); const sys = $('#pg-system').value.trim(); const out = $('#pg-out'), raw = $('#pg-raw'), trace = $('#pg-trace'), badge = $('#pg-status'); out.value = ''; raw.textContent = ''; badge.textContent = 'sending…'; const t0 = performance.now(); let ttft = 0; const headers = { 'Content-Type': 'application/json' }; if (key) { if (proto === 'anthropic') headers['x-api-key'] = key; else headers.Authorization = 'Bearer ' + key; } let body; if (proto === 'anthropic') body = { model, max_tokens: max, temperature: temp, stream, messages: [{ role: 'user', content: prompt }], ...(sys ? { system: sys } : {}) }; else body = { model, temperature: temp, max_tokens: max, stream, messages: [...(sys ? [{ role: 'system', content: sys }] : []), { role: 'user', content: prompt }], ...(stream ? { stream_options: { include_usage: true } } : {}) }; try { const resp = await fetch(proto === 'anthropic' ? '/v1/messages' : '/v1/chat/completions', { method: 'POST', headers, body: JSON.stringify(body) }); const traceHeaders = ['x-gateway-deployment', 'x-gateway-provider', 'x-gateway-upstream-model', 'x-gateway-virtual-endpoint', 'x-gateway-route-profile', 'x-nexaroute-cache', 'x-request-id']; const th = Object.fromEntries(traceHeaders.map(h => [h, resp.headers.get(h)]).filter(([, v]) => v)); let usage = null, text = '', rawText = ''; if (stream && resp.body) { const reader = resp.body.getReader(); const dec = new TextDecoder(); let buf = ''; for (;;) { const { done, value } = await reader.read(); if (done) break; if (!ttft) ttft = performance.now() - t0; const chunk = dec.decode(value, { stream: true }); rawText += chunk; buf += chunk; let idx; while ((idx = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, idx).trim(); buf = buf.slice(idx + 1); if (!line.startsWith('data:')) continue; const data = line.slice(5).trim(); if (!data || data === '[DONE]') continue; try { const j = JSON.parse(data); if (proto === 'anthropic') { if (j.type === 'content_block_delta') text += j.delta?.text || ''; if (j.type === 'message_start') usage = { ...(usage || {}), input_tokens: j.message?.usage?.input_tokens }; if (j.type === 'message_delta' && j.usage) usage = { ...(usage || {}), output_tokens: j.usage.output_tokens }; } else { text += j.choices?.[0]?.delta?.content || ''; if (j.usage) usage = j.usage; } } catch { /* partial line */ } out.value = text; } } raw.textContent = rawText; } else { const j = await resp.json().catch(() => null); raw.textContent = j ? JSON.stringify(j, null, 2) : ''; if (j) { if (proto === 'anthropic') { text = (j.content || []).filter(b => b.type === 'text').map(b => b.text).join(''); usage = j.usage; } else { text = j.choices?.[0]?.message?.content || ''; usage = j.usage; } if (!resp.ok) text = j.error?.message || `HTTP ${resp.status}`; } out.value = text; } const ms = Math.round(performance.now() - t0); const dep = th['x-gateway-deployment'] || ''; const prices = pgPrices(dep); const inTok = usage?.input_tokens ?? usage?.prompt_tokens, outTok = usage?.output_tokens ?? usage?.completion_tokens; const cost = prices && inTok !== undefined && outTok !== undefined && (prices.input || prices.output) ? '$' + ((inTok / 1e6) * prices.input + (outTok / 1e6) * prices.output).toFixed(4) : 'unpriced'; badge.textContent = `HTTP ${resp.status} · ${ms} ms`; trace.innerHTML = `<div class="check-list"><div class="model-row"><span><b>Trace</b><small>${Object.entries(th).map(([k, v]) => `${esc(k)}: ${esc(v)}`).join(' · ') || 'no gateway headers'}</small></span></div><div class="model-row"><span><b>Timing</b><small>total ${ms} ms${ttft ? ` · first byte ${Math.round(ttft)} ms` : ''} · streaming ${stream ? 'on' : 'off'}</small></span></div><div class="model-row"><span><b>Usage</b><small>${inTok !== undefined ? `${num(inTok)} in · ${num(outTok || 0)} out tokens` : 'no usage reported'} · estimated cost ${cost}</small></span></div></div>`; } catch (e) { badge.textContent = 'failed'; trace.innerHTML = `<p class="muted">${esc(e.message)}</p>`; } }
  function paletteCommands() { const pages = Object.entries(meta).map(([id, m]) => ({ label: `Go to ${m[0]}`, hint: 'page', run: () => { state.page = id; render(); } })); const acts = [{ label: 'Refresh data', hint: 'action', run: () => refresh() }, { label: 'Add provider', hint: 'action', run: () => openProvider() }, { label: 'Add route', hint: 'action', run: () => openRoute() }, { label: 'Guided first route', hint: 'action', run: () => openFirstRouteWizard() }, { label: 'Create virtual key', hint: 'action', run: () => actions['create-key']() }, { label: state.drain?.draining ? 'Resume traffic' : 'Start graceful drain', hint: 'action', run: () => actions['toggle-drain']() }, { label: 'Toggle light/dark theme', hint: 'action', run: () => $('#theme-toggle').click() }, { label: 'Open Prometheus metrics', hint: 'link', run: () => window.open('/metrics', '_blank', 'noopener') }, { label: 'Keyboard shortcuts', hint: 'help', run: () => openShortcuts() }]; return [...pages, ...acts]; }
